457:     if (this.keys.has("KeyD") || this.keys.has("ArrowRight")) strafe += 1;
458:     if (this.keys.has("KeyA") || this.keys.has("ArrowLeft")) strafe -= 1;
459:     if (this.touchMove.active) {
