484:       if (event.repeat) {
485:         if (["KeyW", "KeyA", "KeyS", "KeyD", "ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"].includes(event.code)) {
486:           this.keys.add(event.code);
487:         }
488:         return;
489:       }
490:       if (event.code === "Escape") {
491:         if (this.howtoOpen) {
492:           this.closeHowTo();
