494:         }
495:         if (this.state === "paused") this.resumeGame();
496:         else if (this.state === "fight" || this.state === "roundIntro") this.pauseGame();
497:         else if (this.state === "select") this.returnToMenu();
498:         return;
499:       }
500:       if (["KeyW", "KeyA", "KeyS", "KeyD", "ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"].includes(event.code)) {
501:         this.keys.add(event.code);
502:       }
503:       if (event.code === "ShiftLeft" || event.code === "ShiftRight") {
504:         this.keyboardBlock = true;
505:       }
506:       if (this.state === "menu" && (event.code === "Enter" || event.code === "Space")) {
507:         this.showSelect();
508:         return;
