408:   playMove(key) {
409:     const move = MOVES[key];
410:     if (!move || this.action || this.blocking || this.downed || this.ko) return false;
411:     this.action = {
412:       key,
413:       move,
414:       t: 0,
415:       arm: key === "jab" || key === "heavy" ? this.alternateArm : "l",
416:       hitConsumed: false,
417:     };
418:     if (key === "jab") this.alternateArm = this.alternateArm === "l" ? "r" : "l";
419:     if (key === "heavy") this.alternateArm = this.alternateArm === "l" ? "r" : "l";
420:     return true;
421:   }
422: 
423:   cancelAction() {
424:     this.action = null;
425:   }
426: 
427:   setBlocking(value) {
428:     if (this.ko || this.downed) this.blocking = false;
429:     else this.blocking = value;
430:   }
431: 
432:   isAttacking() {
433:     return !!this.action;
434:   }
435: 
436:   isInWindup() {
437:     return !!this.action && this.action.t < this.action.move.windup;
438:   }
439: 
440:   hitLanded() {
441:     if (!this.action || this.action.hitConsumed) return false;
442:     if (this.action.t < this.action.move.hitAt) return false;
443:     this.action.hitConsumed = true;
444:     return true;
445:   }
446: 
447:   takeHit(heavy = false) {
448:     this.hurtTimer = heavy ? 0.5 : 0.32;
449:     this.blocking = false;
450:     if (this.action) this.cancelAction();
451:     if (this.downed) return;
452:   }
453: 
454:   knockDown(duration = 2.0) {
455:     this.cancelAction();
456:     this.blocking = false;
457:     this.downed = true;
458:     this.downTimer = duration;
459:     this.hurtTimer = 0;
460:   }
461: 
462:   setKO() {
463:     this.cancelAction();
464:     this.blocking = false;
465:     this.ko = true;
466:     this.downed = true;
467:     this.downTimer = 0;
468:     this.hurtTimer = 0;
469:   }
470: 
471:   setVictory(value) {
472:     this.celebrating = value;
473:     if (value) {
474:       this.action = null;
475:       this.blocking = false;
476:     }
477:   }
