479:   reset() {
480:     this.action = null;
481:     this.blocking = false;
482:     this.downed = false;
483:     this.downTimer = 0;
484:     this.ko = false;
485:     this.hurtTimer = 0;
486:     this.celebrating = false;
487:     this.invulnerable = 0;
488:     this.locomotion = 0;
489:     this.visual.rotation.x = 0;
490:     this.visual.position.set(0, 0, 0);
491:     this._initPose();
492:   }
493: 
494:   setBaseY(y) {
495:     this.baseY = y;
496:     this.root.position.y = y;
497:   }
498: 
499:   setFacing(dx, dz, dt = 0.2) {
500:     const target = Math.atan2(dx, dz);
501:     let diff = ((target - this.yaw + Math.PI * 3) % TAU) - Math.PI;
502:     this.yaw += diff * (1 - Math.exp(-12 * dt));
503:     this.root.rotation.y = this.yaw;
504:   }
505: 
506:   update(dt, time, locomotion = 0) {
507:     this.locomotion = locomotion;
508:     if (this.invulnerable > 0) this.invulnerable -= dt;
509:     if (this.hurtTimer > 0) this.hurtTimer -= dt;
510: 
511:     if (this.downed && !this.ko) {
512:       this.downTimer -= dt;
513:       if (this.downTimer <= 0) {
514:         this.downed = false;
515:         this.invulnerable = 0.5;
516:       }
517:     }
518: 
519:     if (this.action) {
520:       this.action.t += dt;
521:       if (this.action.t >= this.action.move.duration) this.action = null;
522:     }
523: 
524:     const walking = Math.min(1, locomotion);
525:     this.walkPhase += dt * (2.3 + walking * 6.2);
526:     const bob = Math.sin(this.walkPhase * 2) * 0.008 * walking + Math.sin(time * 2.2 + (this.side === "left" ? 0 : 1.2)) * 0.008;
527: 
528:     const target = this._targetPose(time, walking);
529:     let rate = 11;
530:     if (this.action) rate = this.action.t < this.action.move.hitAt ? 24 : 16;
531:     if (this.downed || this.ko) rate = 7;
532:     this._blendPose(target, rate, dt);
533:     this._applyPose(bob, dt);
534: 
535:     // Falling / getting up is on the visual wrapper, so gameplay positions stay stable.
536:     const fallTarget = this.ko ? -Math.PI / 2.02 : this.downed ? -Math.PI / 2.15 : 0;
537:     this.visual.rotation.x = damp(this.visual.rotation.x, fallTarget, this.ko ? 4.2 : this.downed ? 7.2 : 8.5, dt);
538:     const fallY = this.ko || this.downed ? 0.1 : 0;
539:     this.visual.position.y = damp(this.visual.position.y, fallY + this.pose.visualY + bob, 8, dt);
540:     this.visual.position.z = damp(this.visual.position.z, this.ko || this.downed ? -0.18 : 0, 7, dt);
541:     this.shadow.material.opacity = this.ko || this.downed ? 0.55 : 0.85;
542:   }
