544:   _targetPose(time, walking) {
545:     const t = {
546:       torsoX: 0.08 + Math.sin(time * 2.2) * 0.012,
547:       torsoY: 0,
548:       torsoZ: 0,
549:       headX: -0.03,
550:       headY: Math.sin(time * 1.5) * 0.02,
551:       headZ: 0,
552:       lArmX: -0.56,
553:       lArmY: 0.16,
554:       lArmZ: 0.2,
555:       lElbowX: -1.72,
556:       lElbowY: 0,
557:       lElbowZ: 0,
558:       rArmX: -0.56,
559:       rArmY: -0.16,
560:       rArmZ: -0.2,
561:       rElbowX: -1.72,
562:       rElbowY: 0,
563:       rElbowZ: 0,
564:       lHipX: -0.2,
565:       lHipY: -0.05,
566:       lHipZ: 0.045,
567:       lKneeX: 0.28,
568:       rHipX: 0.16,
569:       rHipY: 0.06,
570:       rHipZ: -0.045,
571:       rKneeX: 0.3,
572:       visualY: 0,
573:     };
574: 
575:     // head bob / breathing
576:     t.headY += Math.sin(time * 2.6) * 0.032;
577: 
578:     const shuffle = Math.sin(this.walkPhase) * 0.055 * walking;
579:     t.lHipX += shuffle;
580:     t.rHipX -= shuffle;
581:     t.lKneeX += Math.abs(shuffle) * 0.5;
582:     t.rKneeX += Math.abs(shuffle) * 0.5;
583:     t.torsoY += Math.sin(this.walkPhase) * 0.04 * walking;
584: 
585:     if (this.celebrating) {
586:       return {
587:         ...t,
588:         torsoX: -0.06,
589:         torsoY: Math.sin(time * 2.4) * 0.12,
590:         headX: -0.14,
591:         lArmX: -2.76,
592:         lArmY: -0.05,
593:         lArmZ: 0.5,
594:         lElbowX: -0.08,
595:         rArmX: -2.76,
596:         rArmY: 0.05,
597:         rArmZ: -0.5,
598:         rElbowX: -0.08,
599:         lHipX: -0.13,
600:         rHipX: 0.13,
601:         visualY: Math.abs(Math.sin(time * 4.2)) * 0.035,
602:       };
603:     }
604: 
605:     if (this.ko) {
606:       return {
607:         ...t,
608:         torsoX: -0.05,
609:         headX: -0.2,
610:         headY: 0.3,
611:         lArmX: -0.25,
612:         lArmZ: 0.55,
613:         lElbowX: -0.4,
614:         rArmX: -0.25,
615:         rArmZ: -0.55,
616:         rElbowX: -0.4,
617:         lHipX: -0.05,
618:         rHipX: 0.08,
619:         lKneeX: 0.35,
620:         rKneeX: 0.2,
621:       };
622:     }
623: 
624:     if (this.downed) {
625:       return {
626:         ...t,
627:         torsoX: 0.05,
628:         headX: 0.18,
629:         lArmX: -0.3,
630:         lArmZ: 0.4,
631:         lElbowX: -0.6,
632:         rArmX: -0.35,
633:         rArmZ: -0.45,
634:         rElbowX: -0.55,
635:         lHipX: -0.15,
