743:   update(dt, elapsed) {
744:     this.time = elapsed;
745:     if (this.dust) {
746:       this.dust.rotation.y += dt * 0.007;
747:       const positions = this.dust.geometry.attributes.position;
748:       for (let i = 0; i < positions.count; i++) {
