  --ink-2: #0c0e14;
  --paper: #f4f0e8;
  --muted: rgba(236, 235, 230, 0.58);
  --line: rgba(255, 255, 255, 0.14);
  --display: "Barlow Condensed", "Arial Narrow", Impact, sans-serif;
  --body: "Inter", "Helvetica Neue", Arial, sans-serif;
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--body);
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}

body {
  touch-action: manipulation;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

button {
  font: inherit;
  color: inherit;
}

#app {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 100svh;
  overflow: hidden;
  background:
    radial-gradient(circle at 60% 40%, rgba(83, 30, 27, 0.22), transparent 40%),
    #06070a;
  isolation: isolate;
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
